<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
const links=['Overview','Projects','Reports'],active=ref('Overview'),open=ref(false),narrow=ref(false),menuButton=ref<HTMLButtonElement>()
let media:MediaQueryList|undefined
function resize(){narrow.value=!!media?.matches;if(!narrow.value)open.value=false}
function pick(label:string){active.value=label;if(narrow.value){open.value=false;menuButton.value?.focus()}}
function escape(){if(open.value){open.value=false;menuButton.value?.focus()}}
onMounted(()=>{media=window.matchMedia('(max-width:700px)');resize();media.addEventListener('change',resize)})
onBeforeUnmount(()=>media?.removeEventListener('change',resize))
</script>
<template><section class="navbar-footer-usage" aria-label="Navbar and footer demonstration"><p>Fictitious local site shell. Links select a sample view without changing route or saving data.</p><header class="shell-header" @keydown.esc="escape"><nav aria-label="Sample primary navigation"><strong class="brand">Sample workspace</strong><button v-if="narrow" ref="menuButton" type="button" aria-controls="navbar-guide-links" :aria-expanded="open" @click="open=!open">{{open?'Close navigation':'Open navigation'}}</button><div id="navbar-guide-links" class="links" :hidden="narrow&&!open"><a v-for="link in links" :key="link" href="#navbar-sample-content" :aria-current="active===link?'page':undefined" @click.prevent="pick(link)">{{link}}</a></div></nav></header><section id="navbar-sample-content" class="content" aria-label="Sample selected view"><h3>{{active}}</h3><p role="status">{{active}} is selected locally. No external page was opened.</p></section><footer class="shell-footer"><span>Sample workspace · Fictitious content</span><nav aria-label="Sample footer navigation"><a href="#navbar-sample-content" @click.prevent="pick('Help')">Help</a><a href="#navbar-sample-content" @click.prevent="pick('Privacy')">Privacy</a></nav></footer></section></template>
<style scoped>
.navbar-footer-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.shell-header,.shell-footer{padding:16px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.shell-header nav,.links,.shell-footer,.shell-footer nav{display:flex;gap:14px;flex-wrap:wrap;align-items:center}.brand{margin-right:auto}.links a,.shell-footer a{display:inline-flex;align-items:center;min-height:44px;padding:8px;text-decoration:none;border-radius:6px}.links a[aria-current=page]{background:var(--vp-c-brand-soft);text-decoration:underline}.links:not([hidden]){animation:nav-enter 160ms ease-out}.links[hidden]{display:none}.content{padding:24px 8px;min-height:170px}.content h3{margin:0}.shell-footer{justify-content:space-between;font-size:14px}button{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg)}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@keyframes nav-enter{from{opacity:.4;translate:0 -4px}to{opacity:1;translate:0 0}}@media(max-width:700px){.links{width:100%;flex-direction:column;align-items:stretch}.shell-footer{align-items:start;flex-direction:column}}@media(prefers-reduced-motion:reduce){.links:not([hidden]){animation:none}}
</style>
